using BmsDesktop.Infrastructure;
using Npgsql;
namespace BmsDesktop.Finance;
public sealed record CashRequestDetail(string Description,decimal Amount,string Notes);
public sealed record CashRequestGroup(string GroupType,Guid? BarnId,string Title,IReadOnlyList<CashRequestDetail> Details);
public sealed class CashRequestV2Service { private readonly Database _db; public CashRequestV2Service(Database db)=>_db=db; public async Task<Guid> CreateAsync(string number,DateOnly date,string subject,IReadOnlyList<CashRequestGroup> groups,Guid actor){if(groups.Count==0||groups.Any(g=>g.Details.Count==0||g.Details.Any(d=>d.Amount<0)))throw new ArgumentException("Kelompok/rincian pengajuan tidak valid.");return await TransactionGuard.RunAsync(_db,async(cn,tx)=>{var requestId=Guid.NewGuid();await using(var h=new NpgsqlCommand("insert into finance_cash_requests(id,request_number,request_date,subject,created_by) values(@id,@n,@d,@s,@u)",cn,tx)){h.Parameters.AddWithValue("id",requestId);h.Parameters.AddWithValue("n",number);h.Parameters.AddWithValue("d",date.ToDateTime(TimeOnly.MinValue));h.Parameters.AddWithValue("s",subject);h.Parameters.AddWithValue("u",actor);await h.ExecuteNonQueryAsync();}for(var x=0;x<groups.Count;x++){var g=groups[x];var gid=Guid.NewGuid();await using(var gc=new NpgsqlCommand("insert into finance_cash_request_groups(id,request_id,group_type,barn_id,title,sort_order) values(@id,@r,@t,@b,@n,@o)",cn,tx)){gc.Parameters.AddWithValue("id",gid);gc.Parameters.AddWithValue("r",requestId);gc.Parameters.AddWithValue("t",g.GroupType);gc.Parameters.AddWithValue("b",(object?)g.BarnId??DBNull.Value);gc.Parameters.AddWithValue("n",g.Title??"");gc.Parameters.AddWithValue("o",x);await gc.ExecuteNonQueryAsync();}foreach(var d in g.Details){await using var dc=new NpgsqlCommand("insert into finance_cash_request_items(id,request_id,group_id,group_type,barn_id,description,amount,notes) values(@id,@r,@g,@t,@b,@d,@a,@n)",cn,tx);dc.Parameters.AddWithValue("id",Guid.NewGuid());dc.Parameters.AddWithValue("r",requestId);dc.Parameters.AddWithValue("g",gid);dc.Parameters.AddWithValue("t",g.GroupType);dc.Parameters.AddWithValue("b",(object?)g.BarnId??DBNull.Value);dc.Parameters.AddWithValue("d",d.Description);dc.Parameters.AddWithValue("a",d.Amount);dc.Parameters.AddWithValue("n",d.Notes??"");await dc.ExecuteNonQueryAsync();}}return requestId;});} }
